def prod_signs(arr):
    if not arr:
        return None

    sum_abs_values = sum(abs(num) for num in arr)

    product_signs = 1
    for num in arr:
        if num > 0:
            product_signs *= 1
        elif num < 0:
            product_signs *= -1
        else:
            product_signs *= 0

    return sum_abs_values * product_signs

